import 'dart:math';

import 'ai_sandbox_stub.dart'
    if (dart.library.io) 'ai_sandbox_native.dart'
    if (dart.library.js_interop) 'ai_sandbox_web.dart'
    as platform;
import 'ai_sandbox_types.dart';

export 'ai_sandbox_types.dart';

/// A fresh ID is generated by default. Reusing an explicit ID reopens only this
/// debug fixture, not the product's normal workspace.
Future<AiSandbox> createAiSandbox() {
  const supplied = String.fromEnvironment('KOI_AI_RUN_ID');
  final random = Random.secure();
  final id = supplied.isEmpty
      ? List.generate(
          16,
          (_) => random.nextInt(256).toRadixString(16).padLeft(2, '0'),
        ).join()
      : supplied;
  if (!RegExp(r'^[0-9a-f]{32}$').hasMatch(id)) {
    throw ArgumentError(
      'KOI_AI_RUN_ID must be exactly 32 lowercase hexadecimal characters',
    );
  }
  return platform.createSandbox(id);
}
